import json,hashlib
def fp(msgs):
    fps=[]
    pend={}
    for m in msgs:
        if m.get('role')=='assistant' and m.get('tool_calls'):
            for t in m['tool_calls']:
                fn=t.get('function',{})
                pend[t.get('id')]=fn.get('name','')+'\x00'+str(fn.get('arguments',''))
        if m.get('role')=='tool':
            cid=m.get('tool_call_id')
            c=m.get('content')
            if isinstance(c,list): c=' '.join(str(x.get('text','') if isinstance(x,dict) else x) for x in c)
            call=pend.pop(cid,'?')
            fps.append(hashlib.sha256((call+'\x00'+str(c)).encode()).hexdigest()[:8])
    return fps
for tid in ['task_000118_3043e92d','task_001857_24daeef3','task_001098_f5acdd79','task_000506_c13429e7','task_000683_7c966a71','task_001979_a1e24b6f','task_001832_dd672877']:
    msgs=json.load(open(f'{tid}.messages.json'))
    fps=fp(msgs)
    from collections import Counter
    c=Counter(fps)
    top=c.most_common(3)
    # max consecutive run
    maxrun=1;cur=1
    for i in range(1,len(fps)):
        if fps[i]==fps[i-1]: cur+=1; maxrun=max(maxrun,cur)
        else: cur=1
    print(f'{tid}: n_tool={len(fps)} distinct={len(c)} top={top} maxconsec_run={maxrun}')
